"kind": "propose",
"summary": "Readiness probe timeout is too short for the application's startup time",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Readiness probe timeout (2s) is too short for the application's startup time, causing 503 errors",
    "supporting": ["ev-target_events", "ev-rollout_history"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "open"
  },
  {
    "root_cause_class": "still_starting",
    "summary": "Pods are starting but not responding to readiness probes within the 2s timeout",
    "supporting": ["ev-target_events", "ev-pod_states"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "orders",
    "uid": "uid-deployment-orders"
  },
  "params": {
    "container": "app",
    "readiness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Increase readiness probe timeout to 5s to allow application time to start before probe fails",
  "rationale": "Readiness probe failures with 503 errors indicate the application isn't responding to probe requests. The current 2s timeout is likely too short for the application's startup time. Increasing the timeout allows the application to start fully before the probe considers it failed. This is supported by the repeated 503 errors in events and the deployment's readiness status being 0/3.",
  "cited_evidence_ids": ["ev-target_events", "ev-rollout_history", "ev-pod_states"],
  "cited_predicates": ["probe_timeouts", "probe_kills", "crashed_on_its_own"]
}
}

